//! Dashboard localization.
//!
//! The locale is chosen from the `dynamo_lang` cookie (set by the language
//! switcher), then the browser's `Accept-Language`, then English.
//!
//! Server-rendered strings live in [`Texts`]; strings the browser script needs
//! live in [`ClientTexts`] and are embedded as JSON in every page. Both are
//! generated by macros that require an English and a Korean value for every
//! key, so a missing translation is a compile error. Strings that modules
//! provide (module names, settings labels, command descriptions) are translated
//! through [`catalog_ko::ko_catalog`].

use std::{convert::Infallible, fmt::Display};

use axum::{extract::FromRequestParts, http::HeaderMap, http::request::Parts};

mod catalog_ko;

pub(crate) use catalog_ko::ko_catalog;

pub(crate) const LOCALE_COOKIE_NAME: &str = "dynamo_lang";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub(crate) enum Locale {
    #[default]
    En,
    Ko,
}

impl Locale {
    pub(crate) const ALL: [Locale; 2] = [Locale::En, Locale::Ko];

    pub(crate) fn code(self) -> &'static str {
        match self {
            Locale::En => "en",
            Locale::Ko => "ko",
        }
    }

    /// The BCP 47 tag used for `Intl` formatting in the browser.
    pub(crate) fn intl_tag(self) -> &'static str {
        match self {
            Locale::En => "en-US",
            Locale::Ko => "ko-KR",
        }
    }

    /// The language's own name, shown in the language switcher.
    pub(crate) fn native_name(self) -> &'static str {
        match self {
            Locale::En => "English",
            Locale::Ko => "한국어",
        }
    }

    pub(crate) fn from_code(code: &str) -> Option<Self> {
        let primary = code
            .trim()
            .split(['-', '_'])
            .next()
            .unwrap_or_default()
            .to_ascii_lowercase();
        match primary.as_str() {
            "en" => Some(Locale::En),
            "ko" => Some(Locale::Ko),
            _ => None,
        }
    }

    pub(crate) fn t(self) -> &'static Texts {
        match self {
            Locale::En => &TEXTS_EN,
            Locale::Ko => &TEXTS_KO,
        }
    }

    pub(crate) fn client(self) -> &'static ClientTexts {
        match self {
            Locale::En => &CLIENT_EN,
            Locale::Ko => &CLIENT_KO,
        }
    }

    /// Translates a string supplied by a module. Unknown strings are returned
    /// unchanged so new module text is never hidden.
    pub(crate) fn catalog(self, source: &str) -> &str {
        match self {
            Locale::En => source,
            Locale::Ko => ko_catalog(source).unwrap_or(source),
        }
    }

    pub(crate) fn from_headers(headers: &HeaderMap) -> Self {
        cookie_locale(headers)
            .or_else(|| accept_language_locale(headers))
            .unwrap_or_default()
    }
}

impl<S> FromRequestParts<S> for Locale
where
    S: Send + Sync,
{
    type Rejection = Infallible;

    async fn from_request_parts(parts: &mut Parts, _state: &S) -> Result<Self, Self::Rejection> {
        Ok(Locale::from_headers(&parts.headers))
    }
}

fn cookie_locale(headers: &HeaderMap) -> Option<Locale> {
    headers
        .get_all(axum::http::header::COOKIE)
        .iter()
        .filter_map(|value| value.to_str().ok())
        .flat_map(|value| value.split(';'))
        .filter_map(|pair| pair.trim().split_once('='))
        .find(|(name, _)| *name == LOCALE_COOKIE_NAME)
        .and_then(|(_, value)| Locale::from_code(value))
}

fn accept_language_locale(headers: &HeaderMap) -> Option<Locale> {
    let header = headers
        .get(axum::http::header::ACCEPT_LANGUAGE)?
        .to_str()
        .ok()?;
    let mut best: Option<(Locale, f32)> = None;
    for entry in header.split(',') {
        let mut parts = entry.split(';');
        let tag = parts.next().unwrap_or_default();
        let quality = parts
            .find_map(|param| param.trim().strip_prefix("q="))
            .and_then(|value| value.trim().parse::<f32>().ok())
            .unwrap_or(1.0);
        let Some(locale) = Locale::from_code(tag) else {
            continue;
        };
        if quality > 0.0 && best.is_none_or(|(_, current)| quality > current) {
            best = Some((locale, quality));
        }
    }
    best.map(|(locale, _)| locale)
}

/// Replaces `{name}` placeholders in a translated template.
pub(crate) fn fill(template: &str, values: &[(&str, &dyn Display)]) -> String {
    let mut output = template.to_string();
    for (name, value) in values {
        output = output.replace(&format!("{{{name}}}"), &value.to_string());
    }
    output
}

macro_rules! localized_texts {
    (
        $(#[$meta:meta])*
        $name:ident, $en:ident, $ko:ident {
            $($key:ident => $en_value:expr, $ko_value:expr;)*
        }
    ) => {
        $(#[$meta])*
        pub(crate) struct $name {
            $(pub(crate) $key: &'static str,)*
        }

        pub(crate) const $en: $name = $name { $($key: $en_value,)* };
        pub(crate) const $ko: $name = $name { $($key: $ko_value,)* };

        impl $name {
            #[allow(dead_code)]
            pub(crate) fn entries(&self) -> Vec<(&'static str, &'static str)> {
                vec![$((stringify!($key), self.$key),)*]
            }
        }
    };
}

