impl ClientTexts {
    pub(crate) fn to_json(&self, locale: Locale) -> String {
        let mut map = serde_json::Map::new();
        for (key, value) in self.entries() {
            map.insert(
                key.to_string(),
                serde_json::Value::String(value.to_string()),
            );
        }
        map.insert(
            "__locale".to_string(),
            serde_json::Value::String(locale.intl_tag().to_string()),
        );
        // `<` is escaped so the JSON can never terminate its <script> container.
        serde_json::Value::Object(map)
            .to_string()
            .replace('<', "\\u003c")
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::http::HeaderValue;

    fn headers(pairs: &[(&'static str, &'static str)]) -> HeaderMap {
        let mut map = HeaderMap::new();
        for (name, value) in pairs {
            map.append(*name, HeaderValue::from_static(value));
        }
        map
    }

    #[test]
    fn cookie_overrides_accept_language() {
        let map = headers(&[
            ("cookie", "other=1; dynamo_lang=ko"),
            ("accept-language", "en-US,en;q=0.9"),
        ]);
        assert_eq!(Locale::from_headers(&map), Locale::Ko);
    }

    #[test]
    fn accept_language_picks_highest_supported_quality() {
        let map = headers(&[("accept-language", "fr-FR, en;q=0.5, ko-KR;q=0.8")]);
        assert_eq!(Locale::from_headers(&map), Locale::Ko);
        let map = headers(&[("accept-language", "de, en-GB;q=0.7")]);
        assert_eq!(Locale::from_headers(&map), Locale::En);
    }

    #[test]
    fn unsupported_or_missing_language_falls_back_to_english() {
        assert_eq!(Locale::from_headers(&HeaderMap::new()), Locale::En);
        let map = headers(&[("cookie", "dynamo_lang=xx"), ("accept-language", "ja")]);
        assert_eq!(Locale::from_headers(&map), Locale::En);
    }

    #[test]
    fn fill_replaces_named_placeholders() {
        assert_eq!(
            fill("{total}개 중 {active}개", &[("active", &3), ("total", &5)]),
            "5개 중 3개"
        );
    }

    #[test]
    fn every_text_is_translated_and_keeps_placeholders() {
        fn placeholders(value: &str) -> Vec<String> {
            let mut found = Vec::new();
            let mut rest = value;
            while let Some(start) = rest.find('{') {
                let Some(end) = rest[start..].find('}') else {
                    break;
                };
                found.push(rest[start..start + end + 1].to_string());
                rest = &rest[start + end + 1..];
            }
            found.sort();
            found
        }
        for (en, ko) in TEXTS_EN
            .entries()
            .into_iter()
            .zip(TEXTS_KO.entries())
            .chain(CLIENT_EN.entries().into_iter().zip(CLIENT_KO.entries()))
        {
            assert!(!ko.1.trim().is_empty(), "empty Korean text for {}", en.0);
            assert_eq!(
                placeholders(en.1),
                placeholders(ko.1),
                "placeholder mismatch for {}",
                en.0
            );
        }
    }

    #[test]
    fn client_json_cannot_close_its_script_tag() {
        let json = CLIENT_EN.to_json(Locale::En);
        assert!(!json.contains('<'));
        let parsed: serde_json::Value = serde_json::from_str(&json).expect("valid JSON");
        assert_eq!(parsed["__locale"], "en-US");
    }

    #[test]
    fn every_catalog_string_has_a_korean_translation() {
        let registry = dynamo_app::module_registry();
        let mut sources: Vec<&str> = Vec::new();
        let mut push_schema = |schema: &dynamo_module_kit::SettingsSchema| {
            for section in &schema.sections {
                sources.push(section.title);
                sources.extend(section.description);
                for field in &section.fields {
                    sources.push(field.label);
                    sources.extend(field.help_text);
                    if let dynamo_module_kit::SettingsFieldKind::Select { options } = &field.kind {
                        sources.extend(options.iter().map(|option| option.label));
                    }
                }
            }
        };
        let mut module_sources = Vec::new();
        for entry in &registry.catalog().entries {
            module_sources.push(entry.module.display_name);
            module_sources.push(entry.module.description);
            push_schema(&entry.settings);
        }
        let mut owned = Vec::new();
        for entry in &registry.command_catalog().entries {
            owned.push(
                entry
                    .command
                    .category
                    .clone()
                    .unwrap_or_else(|| entry.command.module_display_name.to_string()),
            );
            owned.extend(entry.command.description.clone());
            push_schema(&entry.settings);
        }
        let missing = sources
            .into_iter()
            .chain(module_sources)
            .chain(owned.iter().map(String::as_str))
            .filter(|source| !source.trim().is_empty() && ko_catalog(source).is_none())
            .collect::<Vec<_>>();
        assert!(
            missing.is_empty(),
            "missing Korean catalog entries: {missing:#?}"
        );
    }
}
